import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        // restrict amount to avoid overflow in multiplicate if indirectly reached, but keep wide
        amount = bound(amount, 0, type(uint128).max);
        vm.assume(amount > 0);

        // Deploy a helper that will receive ether and not revert, to ensure Command succeeds
        Helper helper = new Helper();

        address owner = c.Owner();
        vm.deal(owner, amount);

        // Owner sends ether to the contract via Command to set balance
        vm.prank(owner);
        c.Command{value: amount}(address(helper), "");

        // The contract balance should now be equal to amount
        uint256 balBefore = address(c).balance;

        // Owner attempts to withdraw
        vm.prank(owner);
        // Withdraw call may succeed or revert; we capture the result
        try c.withdraw() {
            // if we get here, withdraw succeeded, Owner received the balance
            assertTrue(true);
        } catch {
            // In reference, withdraw always succeeds for Owner when balance > 0
            // In buggy version, withdraw always reverts
            // We assert that a revert means the test fails (distinguishes bug)
            assertTrue(false);
        }
    }
}

