pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address target) public {
        vm.assume(target != address(0) && target != address(c) && target != address(this));
        vm.assume(amount <= address(this).balance);

        // Deploy a re-entrant attacker helper that triggers withdraw during a Command call
        ReentrancyAttacker attacker = new ReentrancyAttacker();
        vm.deal(address(attacker), amount);

        // Owner = this test contract, make Owner the actual owner of c
        // (setUp uses new C(), so msg.sender is this test contract)
        // c's Owner is this contract, so we can call Command directly

        // Fund the attacker with the amount that will be sent to c
        // Attacker will call Command with itself as target and calldata that triggers withdraw.
        // The buggy withdraw always reverts; the reference withdraw works, but the reentrant call
        // in the attacker's receive may change behavior.
        // We check that Owner can later call Command(owner, "") and succeed.

        // Step 1: Owner calls Command on attacker, who will callback into c to trigger withdraw
        bytes memory reentrantPayload = abi.encodeWithSelector(ReentrancyAttacker.attack.selector, address(c), amount);
        // The attacker's attack function will call c.Command with value and data that triggers withdraw reentrancy
        // We prvank as Owner (this contract) and call Command on attacker
        vm.prank(address(this));
        c.Command{value: amount}(address(attacker), reentrantPayload);

        // Step 2: Now Owner tries a second Command call with 0 value and empty data
        bool secondCallSuccess;
        vm.prank(address(this));
        try c.Command(address(this), "") {
            secondCallSuccess = true;
        } catch {
            secondCallSuccess = false;
        }

        assertTrue(secondCallSuccess);
    }
}

contract ReentrancyAttacker {
    C public targetContract;
    uint256 public attackValue;
    bool public attacked;

    function attack(address cAddr, uint256 value) external payable {
        require(msg.value == value, "wrong value");
        targetContract = C(cAddr);
        attackValue = value;
        attacked = false;
        // Call Command on the target to trigger withdraw reentrancy
        bytes memory withdrawCalldata = abi.encodeWithSignature("withdraw()");
        targetContract.Command{value: value}(address(this), withdrawCalldata);
        // After Command returns, we may have received Ether from withdraw
    }

    receive() external payable {
        if (!attacked) {
            attacked = true;
            // Re-enter the target's withdraw (if Command is still executing)
            // This reentrancy can break the mutant's withdraw, causing revert
            targetContract.withdraw();
        }
    }
}

