        // But setUp already deploys c. We can use vm.prank to make adversarialOwner the deployer.
        address deployer = address(adversarialOwner);
        vm.prank(deployer);
        c = new C(); // Owner is adversarialOwner
        vm.deal(address(c), amount);
        // Now call withdraw as the Owner (adversarialOwner)
        vm.prank(address(adversarialOwner));
        (bool success, ) = address(c).call(abi.encodeWithSignature("withdraw()"));
        // After a successful withdraw, balance must be zero. If it reverts, rule doesn't apply.
        if (success) {
            assertTrue(address(c).balance == 0);
