import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address adr, uint256 amount, bytes memory data) public {
        // Restrict amount to avoid overflow in balance calculation
        amount = bound(amount, 0, type(uint256).max / 2);
        vm.assume(adr != address(c)); // prevent self-call reentrancy complexities
        // Fund the contract with some Ether
        vm.deal(address(c), amount);
        // Owner calls Command with the given amount and data
        vm.startPrank(c.Owner());
        uint256 balanceBefore = address(c).balance;
        c.Command{value: amount}(adr, data);
        uint256 balanceAfter = address(c).balance;
        vm.stopPrank();
        // In the reference C, the low-level call may succeed or fail, but the contract's balance
        // must have changed by at most the amount sent, and exactly by amount if the call succeeds.
        // The invariant: balanceAfter >= balanceBefore - amount.
        // The buggy version never transfers value, so balanceAfter == balanceBefore always,
        // which satisfies this inequality, so we need a stronger invariant.
        // Instead, we assert that if the call succeeds (no revert), the balance decrease equals amount.
        // To capture revert, we wrap the call and check balance change.
        bool ok;
        vm.startPrank(c.Owner());
        uint256 balBefore = address(c).balance;
        try c.Command{value: amount}(adr, data) { ok = true; } catch { ok = false; }
        uint256 balAfter = address(c).balance;
        vm.stopPrank();
        if (ok) {
            // If the low-level call succeeded in reference, balance decreased by amount.
            // In buggy, balance stays same, so this assertion fails when ok is true.
            assertEq(balAfter, balBefore - amount);
        } else {
            // If the call reverted, reference's balance is unchanged, buggy also unchanged.
            // No assertion needed here, but we must ensure the property holds for all inputs.
            assertTrue(true);
        }
    }
}

